package org.racedaydreams.domain.strength;

import java.util.List;

/** Original functional-movement instructions; duration and distance are never fake repetitions. */
final class FunctionalTechniqueGuides {
    private FunctionalTechniqueGuides() {}
    static TechniqueGuide forExercise(String id) {
        return switch(id) {
            case "kettlebell-clean" -> g("power","Hold a light kettlebell with one hand and begin in a controlled hinge with clear space around you.","Drive from the hips and guide the bell close into the front rack against the forearm; return smoothly without banging the wrist.","Hips, legs, upper back and grip","Keep the bell close|Use a relaxed controlled turnover|Practise light before loading","Swinging the bell into the wrist|Pulling only with the arm|Overarching at the finish","Kettlebell Swing|Front Rack Carry");
            case "kettlebell-snatch" -> g("power","Use a light bell and coached practice; begin in a controlled one-arm hinge with overhead space clear.","Drive from the hips, guide the bell close and turn the hand through to a stable overhead position; return with control.","Hips, legs, shoulders and grip","Learn the overhead position first|Keep the bell close|Use light practice","Banging the wrist|Forcing shoulder range|Losing trunk control","Kettlebell Clean|Kettlebell Swing");
            case "thruster" -> g("power","Hold two manageable dumbbells at the front shoulders with feet stable and overhead space clear.","Lower into a controlled front squat, then drive upwards into an overhead press; return the weights to the shoulders before repeating.","Legs, hips, shoulders and triceps","Keep heels supported|Keep the weights controlled|Finish with ribs steady","Collapsing into the squat|Overarching overhead|Rushing before balanced","Front Squat|Dumbbell Shoulder Press");
            case "wall-ball" -> g("power","Hold a suitable soft medicine ball at the chest, facing a clear solid wall and an appropriate target.","Squat with control, then stand and throw the ball towards the target; receive it softly and reset before repeating.","Legs, hips, shoulders and trunk","Use a manageable ball|Check the wall and landing space|Receive with control","Standing too close|Catching stiffly near the face|Rushing an unstable squat","Goblet Squat|Thruster");
            case "devil-press" -> g("power","Use light stable hex dumbbells on a clear floor; begin with a controlled push-up position gripping the handles.","Bring feet towards the hands, establish a braced hinge and drive the weights overhead; lower deliberately before returning to the floor.","Legs, hips, chest, shoulders and trunk","Use non-rolling weights|Reset the hinge before lifting|Start light and unhurried","Using unstable round dumbbells|Rounding to rush the lift|Dropping weights near the feet","Dumbbell Snatch|Push-Up");
            case "dumbbell-snatch" -> g("power","Set a light dumbbell between the feet; bend hips and knees, grip one handle and brace.","Drive through legs and hips, guiding the weight close to a stable overhead position; lower deliberately and reset before changing sides.","Legs, hips, shoulders and trunk","Keep the weight close|Learn the overhead position first|Use light coached practice","Swinging far forwards|Pulling mainly with the arm|Lowering without control","Kettlebell Swing|Dumbbell Clean & Jerk");
            case "dumbbell-clean-jerk" -> g("power","Hold two light dumbbells below the knees in a controlled hinge with clear overhead space.","Drive them into the front rack, stand and reset; use a short dip and drive to receive overhead, then stand before lowering.","Legs, hips, shoulders and triceps","Learn each phase separately|Keep weights close|Use a stable receiving position","Rushing an unstable rack|Overarching overhead|Loading before technique is reliable","Dumbbell Shoulder Press|Push Press");
            case "sled-push" -> g("carry","Check the sled, surface and clear path; take a secure grip on its handles and lean forwards with a braced trunk.","Push using short controlled alternating steps while keeping the arms steady; stop and reset before posture fades.","Legs, hips and trunk","Use a clear suitable surface|Keep steps controlled|Choose a manageable load","Slipping on an unsuitable surface|Letting the trunk collapse|Pushing beyond control","Farmer's Carry|Step-Up");
            case "sled-pull" -> g("carry","Face a securely loaded sled holding suitable straps, with the path behind you clear and arms reaching forwards.","Walk backwards in controlled alternating steps, keeping straps taut and trunk steady; stop before balance fades.","Legs, hips and trunk","Check the strap attachment|Keep the path clear|Use short controlled steps","Wrapping straps around the neck|Walking into obstacles|Jerking mainly with the arms","Sled Push|Farmer's Carry");
            case "sandbag-carry" -> g("carry","Hold a manageable sandbag securely against the chest in a bear hug, supporting it with both arms.","Walk in short controlled steps while breathing; set the bag down safely before grip or posture becomes difficult.","Trunk, upper back, arms and legs","Keep the bag close|Use a clear path|Breathe steadily","Leaning backwards|Carrying beyond control|Dropping the bag near the feet","Farmer's Carry|Front Rack Carry");
            case "sandbag-clean" -> g("power","Place a manageable sandbag between the feet and take a secure grip with hips and knees bent.","Bring the bag into the lap, re-grip securely and stand into a front bear-hug position; lower deliberately rather than dropping near the feet.","Legs, hips, trunk and upper back","Keep the bag close|Reset the grip in the lap|Start light","Rounding to yank the bag|Throwing it towards the face|Rushing an insecure grip","Sandbag Carry|Romanian Deadlift");
            case "ghd-sit-up" -> g("core","Adjust a glute-ham developer with hips supported and feet secure under the rollers; begin sitting upright.","Lean back only through a comfortable controlled range, no lower than horizontal in this illustration, then return without jerking.","Abdominals and hip flexors","Use a short range first|Check ankle support|Keep movement controlled","Dropping into deep back extension|Unsecured feet|Jerking the neck to return","Dead Bug|Weighted Sit-Up");
            default -> null;
        };
    }
    private static TechniqueGuide g(String pattern,String setup,String movement,String muscles,String cues,String mistakes,String alternatives) {
        return new TechniqueGuide(pattern,setup,movement,List.of(cues.split("\\|")),List.of(mistakes.split("\\|")),muscles,List.of(alternatives.split("\\|")));
    }
}
